using System;using System.Drawing;using System.IO;using System.Reflection;using System.Runtime.Serialization;using System.Windows.Forms;
class AfterSavePromptRegression{
 const BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;static Assembly app;static int checks;
 static object Field(object o,string n){return o.GetType().GetField(n,F).GetValue(o);}static object Get(object o,string n){return o.GetType().GetProperty(n,F).GetValue(o,null);}static void Set(object o,string n,object v){o.GetType().GetProperty(n,F).SetValue(o,v,null);}static void Put(object o,string n,object v){o.GetType().GetField(n,F).SetValue(o,v);}static object Call(object o,string n,params object[]a){try{return o.GetType().GetMethod(n,F).Invoke(o,a);}catch(TargetInvocationException e){throw e.InnerException;}}static void Check(bool b,string m){if(!b)throw new Exception(m);checks++;}
 static Control Bare(string name,Type baseType){var o=FormatterServices.GetUninitializedObject(app.GetType(name));baseType.GetConstructor(Type.EmptyTypes).Invoke(o,new object[0]);return (Control)o;}
 static void Saved(object design,EventArgs e,string action){bool seen=false;Exception failure=null;using(var timer=new Timer{Interval=20}){timer.Tick+=delegate{foreach(Form d in Application.OpenForms){if(d.GetType().Name!="DialogOrderSaved")continue;timer.Stop();seen=true;try{Check(((Control)Field(d,"labelMessage")).Text=="저장되었습니다. 새로운 작업을 시작할까요?","Exact saved prompt");Check(((Button)Field(d,"btnNewWork")).Text=="예"&&((Button)Field(d,"btnManagement")).Text=="아니오(관리모드로 돌아가기)","Exact action labels");Check(ReferenceEquals(d.AcceptButton,Field(d,"btnNewWork")),"Enter starts next work");Check(d.ClientRectangle.Contains(((Control)Field(d,"btnManagement")).Bounds),"Long management button fits dialog");if(action=="close")d.Close();else ((IButtonControl)Field(d,action)).PerformClick();}catch(Exception ex){failure=ex;d.Close();}break;}};timer.Start();Call(design,"OrderDesigner_OrderSaved",design,e);timer.Stop();}if(failure!=null)throw failure;Check(seen==(action!=null),"Prompt is skipped for work-order save");}
 [STAThread]static int Main(string[]args){try{Application.EnableVisualStyles();app=Assembly.LoadFrom(Path.GetFullPath(args[0]));using(var main=(Form)Bare("PineTree.Forms.FormMain",typeof(Form)))using(var management=Bare("PineTree.UserControls.UcContainer",typeof(UserControl)))using(var pad=Bare("PineTree.UserControls.UcOrderDesignPad",typeof(UserControl))){Call(main,"InitializeComponent");Call(pad,"InitializeComponent");Call(pad,"InitOrderItemTable");Call(pad,"InitOrderEditor");Call(pad,"InitPreviewEvent");var type=app.GetType("PineTree.UserControls.UcDesignModeContainer");using(var design=(Control)type.GetConstructor(F,null,new[]{pad.GetType()},null).Invoke(new object[]{pad})){var panel=(Panel)Field(main,"panel1");panel.Controls.Add(management);panel.Controls.Add(design);Put(main,"_managementContainer",management);Put(main,"_designModeContainer",design);Call(main,"InitializeModeControls");Call(main,"SetManagementMode",false);int refresh=0,requests=0;type.GetEvent("OrderSaved").AddEventHandler(design,new EventHandler(delegate{refresh++;}));type.GetEvent("ManagementModeRequested").AddEventHandler(design,Delegate.CreateDelegate(typeof(EventHandler),main,main.GetType().GetMethod("DesignModeContainer_ManagementModeRequested",F)));type.GetEvent("ManagementModeRequested").AddEventHandler(design,new EventHandler(delegate{requests++;}));
 Set(Field(pad,"tbRemark"),"Text","saved draft");Put(pad,"m_orderId",44L);Saved(design,(EventArgs)Activator.CreateInstance(app.GetType("PineTree.UserControls.OrderSavedForWorkOrderEventArgs"),true),null);Check((string)Get(Field(pad,"tbRemark"),"Text")=="saved draft"&&(long)Field(pad,"m_orderId")==44L,"Work-order save keeps editing state");Check(refresh==1&&requests==0,"Work-order save refreshes dashboard without changing mode");
 Saved(design,EventArgs.Empty,"btnNewWork");Check((string)Get(Field(pad,"tbRemark"),"Text")==""&&(long)Field(pad,"m_orderId")==-1L,"Yes resets saved work");Check(!(bool)Field(main,"_isManagementMode")&&requests==0,"Yes remains in design mode");
 Set(Field(pad,"tbRemark"),"Text","second saved work");Saved(design,EventArgs.Empty,"btnManagement");Check((bool)Field(main,"_isManagementMode")&&requests==1,"No returns to management mode");Check((string)Get(Field(pad,"tbRemark"),"Text")=="","No clears saved work before leaving");
 Call(main,"SetManagementMode",false);Set(Field(pad,"tbRemark"),"Text","third saved work");Saved(design,EventArgs.Empty,"close");Check(!(bool)Field(main,"_isManagementMode")&&(string)Get(Field(pad,"tbRemark"),"Text")=="","Closing prompt safely prepares next work");Check(refresh==4,"Dashboard refresh notified on every successful save");
 }}Console.WriteLine("PASS: "+checks+" post-save prompt and navigation checks");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
